for et,v in ei.items():
    for d in v:
        kn='%s_%s_%s'%(d['mname'],d['datexp'],d['blk'])
        maps.setdefault(kn,[]).append((et,d.get('stimtype',''),np.asarray(d['stim_id'],dtype=float)))
rows=json.load(open('/tmp/sess_stats.json'))
allw=collections.Counter()
for r in rows:
    for w,c in r['walls'].items(): allw[w]+=c
print('distinct walls:',dict(allw))
print()
canon=['circle1','circle2','leaf1','leaf2','leaf3','leaf1_swap1','leaf1_swap2']
# need UniqWalls per session: reconstruct as sorted unique wall names
conflict=0
for r in rows:
    uniq=sorted(r['walls'].keys())
    merged={}
    for et,st,sid in maps[r['kn']]:
        if len(sid)!=len(uniq): print('LEN MISMATCH',r['kn'],et,len(sid),uniq); continue
        for w,s in zip(uniq,sid):
            if not np.isnan(s):
                if w in merged and merged[w]!=int(s): print('CONFLICT',r['kn'],w,merged[w],int(s)); 
                merged[w]=int(s)
    unmapped=[w for w in uniq if w not in merged]
    if unmapped: print(r['kn'], 'unmapped:',unmapped,'mapped:',{w:canon[merged[w]] for w in merged})
" 2>&1 | head -60

